sysauto_script.script:
// Now Assist Cost Lens — Nightly Analytics
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// Runs daily at 03:00. Computes ROI, detects waste, forecasts spend,
// checks anomalies, and fires alerts if thresholds exceeded.

(function() {
    try {
        var engine = new NACLAnalyticsEngine();

        // 1. Compute ROI for last 30 days
        var roi = engine.computeROI(30);
        gs.info('NACL Nightly: ROI computed — net savings: ' + roi.net_savings.toFixed(2) +
                ', resolution rate: ' + roi.resolution_rate + '%');

        // 2. Detect waste for last 7 days
        var waste = engine.detectWaste(7);
        gs.info('NACL Nightly: Waste detected — ' + waste.total_waste_interactions +
                ' wasteful interactions, total cost: ' + waste.total_waste_cost.toFixed(2));

        // 3. Forecast next month
        var forecast = engine.forecastSpend(30);
        gs.info('NACL Nightly: Forecast — projected: ' + forecast.projected_cost.toFixed(2) +
                ', exceeds budget: ' + forecast.exceeds_budget);

        // 4. Check anomalies
        var anomalies = engine.checkAnomalies();
        if (anomalies.length > 0) {
            gs.warn('NACL Nightly: ' + anomalies.length + ' cost anomalies detected');
        }

        // 5. Clean up old logs per retention policy
        var config = engine.tracker._readCostConfig();
        var retentionDays = parseInt(config.data_retention_days) || 365;
        var cutoffGdt = new GlideDateTime();
        cutoffGdt.addSeconds(-retentionDays * 86400);

        var logGr = new GlideRecord('x_nacl_interaction_log');
        logGr.addQuery('captured_at', '<', cutoffGdt.toString());
        logGr.query();

        var deleted = 0;
        while (logGr.next()) {
            try {
                logGr.deleteRecord();
                deleted++;
            } catch (e) {
                gs.error('NACL Nightly: Failed to delete old log ' + logGr.getUniqueValue() + ': ' + e.message);
            }
        }

        if (deleted > 0) {
            gs.info('NACL Nightly: Cleaned up ' + deleted + ' interaction logs older than ' + retentionDays + ' days');
        }

        gs.info('NACL Nightly: Analytics run complete');
    } catch (e) {
        gs.error('NACL Nightly: Fatal error in nightly analytics: ' + e.message);
    }
})();
